export type PortfolioOperationType = 'EURO_FUND_INTEREST' | 'PROFIT_SHARING' | 'MANAGEMENT_FEE' | 'SOCIAL_CONTRIBUTION' | 'PREMIUM' | 'PARTIAL_SURRENDER' | 'FULL_SURRENDER' | 'SWITCH' | 'DEPOSIT' | 'WITHDRAWAL' | 'BUY' | 'SELL' | 'DIVIDEND' | 'INTEREST' | 'FEE' | 'TAX' | 'SECURITY_TRANSFER_IN' | 'SECURITY_TRANSFER_OUT' | 'SPLIT' | 'MERGER' | 'SPIN_OFF';

