    counterInstrument: PortfolioOperationInstrument | null;
    quantity: PortfolioDecimal | null;
    unitPrice: PortfolioDecimal | null;
    grossAmount: DecimalAmount | null;
    fees: DecimalAmount | null;
    taxes: DecimalAmount | null;
    /**
     * The signed cash effect the server derived. Never sent by the client.
     */
    cashAmount: DecimalAmount;
    costBasis: DecimalAmount | null;
    counterQuantity: PortfolioDecimal | null;
    ratio: PortfolioOperationRatio | null;
    costAllocationRatio: PortfolioDecimal | null;
    /**
     * Gross amount minus quantity x unit price, exact, for a buy or a sell; null otherwise.
     */
    roundingResidual: DecimalAmount | null;
    reference: string | null;
    note: string | null;
    linkedTransactionId: string | null;
    state: 'ACTIVE' | 'VOIDED';
    voidedAt: string | null;
