export type PortfolioOperationProblem = Problem & {
    code: 'account_not_portfolio' | 'portfolio_account_inactive' | 'life_insurance_contract_required' | 'life_insurance_contract_closed' | 'operation_type_not_allowed_for_account' | 'instrument_not_euro_fund' | 'invalid_interest_basis' | 'invalid_year' | 'euro_fund_price_fixed' | 'invalid_operation_type' | 'unsupported_operation_type' | 'operation_field_required' | 'operation_field_not_allowed' | 'invalid_operation_amount' | 'invalid_operation_quantity' | 'quantity_precision_exceeded' | 'price_precision_exceeded' | 'operation_asset_mismatch' | 'instrument_inactive' | 'instrument_currency_mismatch' | 'surrender_exceeds_available' | 'premium_allocation_exceeds_net' | 'leg_amount_mismatch' | 'unknown_leg_instrument' | 'duplicate_leg_instrument' | 'invalid_leg_direction' | 'switch_same_support' | 'switch_not_balanced' | 'too_many_operation_legs' | 'invalid_surrender_amounts' | 'full_surrender_positions_remaining' | 'full_surrender_not_balanced' | 'operations_after_full_surrender' | 'unknown_instrument' | 'invalid_corporate_action' | 'invalid_operation_date' | 'invalid_settlement_date' | 'operation_amount_mismatch' | 'linked_transfer_mismatch' | 'invalid_operation_text' | 'invalid_operation_payload' | 'invalid_operation_query' | 'invalid_position_query' | 'invalid_cash_query' | 'cash_range_too_large' | 'cash_range_too_dense' | 'cash_amount_too_large' | 'portfolio_account_not_found' | 'portfolio_operation_not_found' | 'portfolio_instrument_not_found' | 'stale_operation_version' | 'stale_operation_order' | 'operation_voided' | 'linked_transfer_taken' | 'operation_limit_reached' | 'portfolio_operation_conflict' | 'portfolio_forbidden' | 'portfolio_payload_too_large' | 'position_would_go_negative' | 'split_fraction_unsupported' | 'corporate_action_without_position';
    legIndex?: number;
    /**
     * Exact quantity times price on leg_amount_mismatch.
     */
    expectedAmount?: string;
    /**
     * Exact outgoing sum less fees on switch_not_balanced.
     */
    expectedIncomingAmount?: string;
    /**
     * Supports remaining after a full surrender.
     */
    instrumentIds?: Array<string>;
    /**
     * The matrix field named by `operation_field_required` and `operation_field_not_allowed`.
     */
    field?: string;
    /**
     * Exact expected gross on operation_amount_mismatch or full_surrender_not_balanced.
     */
    expectedGrossAmount?: string;
    operationId?: string;
    tradeDate?: string;
    instrumentId?: string;
};

/**
 * A financial decimal. Every amount, quantity, price and rate travels as a canonical decimal string paired with its asset code; a native JSON number is forbidden, because parsing one would put a binary float back into a financial value.
 */
export type DecimalAmount = {
    value: string;
    assetCode: string;
};

/**
 * The metric policy that produced a figure. `version` is null when a period mixes several versions.
 */
export type MetricPolicyReference = {
    version: number | null;
    label: string | null;
};

export type MetricPolicy = {
    version: number;
    label: string;
    cashExcludedAccountKinds: Array<AccountKind>;
    savingsRateFormula: 'BUDGET_SURPLUS_OVER_CASH_INCOME';
    netSavingsRateFormula: 'NET_SAVINGS_TRANSFERS_OVER_CASH_INCOME';
    createdAt: string | null;
    system: boolean;
};

export type MetricPolicyCatalog = {
    /**
     * The active definition, or null when the active version cannot be loaded. `activeVersion` then names the unresolvable version.
     */
    active: MetricPolicy | null;
    activeVersion: number;
    activeSince: string | null;
    versions: Array<MetricPolicy>;
};

export type ActiveMetricPolicy = {
    active: MetricPolicy;
    activeSince: string;
};

export type CreateMetricPolicyRequest = {
    label: string;
    cashExcludedAccountKinds: Array<AccountKind>;
};

export type ActivateMetricPolicyRequest = {
    version: number;
    expectedActiveVersion: number;
    reason?: string;
};

export type MetricPolicyProblem = Problem & {
    code?: 'policy_definition_exists' | 'policy_version_limit' | 'stale_active_policy' | 'policy_already_active' | 'activation_limit' | 'unknown_policy_version';
    version?: number;
};

/**
 * An RFC 9457 problem detail. Extension members are allowed; specialised problems compose it with allOf.
 */
export type Problem = {
    type: string;
    title: string;
    status: number;
    detail: string;
};

/**
 * Invalid account group input. Invalid colors include a field error without reflecting submitted data.
 */
export type AccountGroupInputProblem = Problem & {
    errors?: Array<{
        field: 'color';
        code: 'INVALID_COLOR';
    }>;
};

/**
 * An RFC 9457 problem raised by the shared exact-amount parser. The JSON pointer names the public request member that failed validation.
 */
export type AmountInputProblem = Problem & {
    type?: unknown;
    status?: 422;
    pointer: string;
};

/**
 * Raised when an income, expense, refund or fee would be booked on an account valued by its portfolio, which would count the same money twice. Record a portfolio operation instead; transfers and adjustments stay allowed.
 */
export type PortfolioAccountRequiresOperationsProblem = Problem & {
    type?: '/problems/portfolio-account-requires-operations';
    status?: 422;
    code: 'portfolio_account_requires_operations';
    accountId: string;
};

/**
 * Raised by the transaction update, void and split-replacement endpoints when the targeted transaction is a transfer leg or its fee: only the transfer's own endpoint may change it.
 */
export type TransactionBelongsToTransferProblem = Problem & {
    type?: '/problems/transaction-belongs-to-transfer';
    status?: 422;
    /**
     * The transfer to use instead.
     */
    transferId: string;
};

export type PeriodClosingCondition = 'UNRECONCILED_ACCOUNT' | 'UNEXPLAINED_DISCREPANCY' | 'PENDING_TRANSACTIONS' | 'MISSING_PORTFOLIO_VALUATION';

